/**
 * Parent-listing neighbors for a Read / LS miss. FileSystem has no
 * catalog API; `list(dirname(path))` is the sibling set. Immediate
 * children only — a recursive mount must not dump its whole subtree.
 */
import { posix } from "node:path";
import { FILE_SYSTEM_SCAN_LIMIT, normalizeFsPath } from "../../filesystem.js";
import { collectList } from "./walk.js";
const NEIGHBOR_LIMIT = 5;
export function nearestListedNames(query, names, limit = NEIGHBOR_LIMIT) {
    const queryKey = rankKey(query);
    return [...names]
        .sort((left, right) => {
        const leftKey = rankKey(left);
        const rightKey = rankKey(right);
        const leftPrefix = isPrefixRelated(queryKey, leftKey) ? 0 : 1;
        const rightPrefix = isPrefixRelated(queryKey, rightKey) ? 0 : 1;
        if (leftPrefix !== rightPrefix) {
            return leftPrefix - rightPrefix;
        }
        const distance = editDistance(queryKey, leftKey) - editDistance(queryKey, rightKey);
        return distance !== 0 ? distance : left.localeCompare(right);
    })
        .slice(0, limit);
}
export function formatMissNeighborHint(path, neighbors) {
    if (neighbors.length === 0) {
        return undefined;
    }
    return `not found: ${path}. nearest: ${neighbors.join(", ")}. do not retry.`;
}
/**
 * One-line miss hint when the parent directory listed siblings.
 * `undefined` leaves the caller to throw the ordinary miss.
 * @deprecated Deprecated on the package root.
 */
export async function nearestNeighborMissHint(root, path) {
    const missed = normalizeFsPath(path);
    const parent = parentDir(missed);
    const files = await collectList(root, parent, {
        limit: FILE_SYSTEM_SCAN_LIMIT,
    });
    const names = [
        ...new Set(files
            .map((file) => relativeToParent(file.path, parent))
            .filter((name) => name.length > 0 && !name.includes("/"))),
    ].filter((name) => name !== posix.basename(missed));
    return formatMissNeighborHint(missed, nearestListedNames(posix.basename(missed), names));
}
function rankKey(name) {
    const base = posix.basename(name);
    const dot = base.lastIndexOf(".");
    return dot > 0 ? base.slice(0, dot) : base;
}
function isPrefixRelated(left, right) {
    return left.startsWith(right) || right.startsWith(left);
}
function editDistance(left, right) {
    const previous = Array.from({ length: right.length + 1 }, (_, index) => index);
    for (let i = 0; i < left.length; i += 1) {
        let diagonal = i;
        previous[0] = i + 1;
        for (let j = 0; j < right.length; j += 1) {
            const insertion = (previous[j + 1] ?? 0) + 1;
            const deletion = (previous[j] ?? 0) + 1;
            const substitution = diagonal + (left[i] === right[j] ? 0 : 1);
            diagonal = previous[j + 1] ?? 0;
            previous[j + 1] = Math.min(insertion, deletion, substitution);
        }
    }
    return previous[right.length] ?? right.length;
}
function parentDir(path) {
    const dir = posix.dirname(path);
    return dir === "." || dir === path ? "/" : dir;
}
function relativeToParent(filePath, parent) {
    const file = normalizeFsPath(filePath);
    const root = parent === "/" || parent === "" ? "/" : normalizeFsPath(parent);
    if (root === "/") {
        return file.startsWith("/") ? file.slice(1) : file;
    }
    if (file === root) {
        return posix.basename(file);
    }
    if (file.startsWith(`${root}/`)) {
        return file.slice(root.length + 1);
    }
    return posix.basename(file);
}
